import subprocess, pty, os as osmod, select

def run_with_tty(args, inp):
    master, slave = pty.openpty()
    p = subprocess.Popen(['./executable']+args, stdin=subprocess.PIPE, stdout=slave, stderr=subprocess.PIPE, text=True)
    osmod.close(slave)
    try:
        p.stdin.write(inp)
        p.stdin.close()
    except: pass
    output = b""
    try:
        while True:
            r, _, _ = select.select([master], [], [], 2)
            if not r:
                break
            try:
                data = osmod.read(master, 4096)
                if not data:
                    break
                output += data
            except OSError:
                break
    finally:
        osmod.close(master)
        try:
            p.wait(timeout=5)
        except: p.kill()
        try:
            stderr = p.stderr.read() if p.stderr else ""
        except: stderr=""
    return output, stderr, p.returncode

