const helpText = "Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable\n\nUsage:\n  gron [OPTIONS] [FILE|URL|-]\n\nOptions:\n  -u, --ungron     Reverse the operation (turn assignments back into JSON)\n  -v, --values     Print just the values of provided assignments\n  -c, --colorize   Colorize output (default on tty)\n  -m, --monochrome Monochrome (don't colorize output)\n  -s, --stream     Treat each line of input as a separate JSON object\n  -k, --insecure   Disable certificate validation\n  -x, --proxy      Set proxy configuration\n      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.\n  -j, --json       Represent gron data as JSON stream\n      --no-sort    Don't sort output (faster)\n      --version    Print version information\n\nExit Codes:\n  0\tOK\n  1\tFailed to open file\n  2\tFailed to read input\n  3\tFailed to form statements\n  4\tFailed to fetch URL\n  5\tFailed to parse statements\n  6\tFailed to encode JSON\n\nExamples:\n  gron /tmp/apiresponse.json\n  gron http://jsonplaceholder.typicode.com/users/1 \n  curl -s http://jsonplaceholder.typicode.com/users/1 | gron\n  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron\n"

var reserved = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "false": true, "finally": true,
	"for": true, "function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true, "super": true,
	"switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
	"yield": true,
}

func isBare(s string) bool {
	if s == "" {
		return false
	}
	if reserved[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if r == '$' || r == '_' {
				continue
			}
			if unicode.IsOneOf([]*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl}, r) {
				continue
			}
			return false
		} else {
			if r == '$' || r == '_' {
				continue
			}
			if unicode.IsOneOf([]*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc}, r) {
				continue
			}
			return false
		}
	}
	return true
}

// for ungron bare check: allow reserved? Need to check: ungron allows bare reserved like true, if, etc.
// So isBareUngron should not check reserved, but same unicode rules?
// Test: json.true valid, json.if valid, json.0a invalid, json.é valid, json.🎉 invalid
// So same unicode rules, but without reserved check.
func isBareUngron(s string) bool {
	if s == "" {
		return false
	}
	// no reserved check
	for i, r := range s {
		if i == 0 {
			if r == '$' || r == '_' {
				continue
			}
			if unicode.IsOneOf([]*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl}, r) {
				continue
			}
			return false
		} else {
			if r == '$' || r == '_' {
				continue
			}
			if unicode.IsOneOf([]*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc}, r) {
				continue
			}
			return false
		}
	}
	return true
}

func encodeGronString(s string) string {
	var buf bytes.Buffer
	buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			buf.WriteString("\\\"")
		case '\\':
			buf.WriteString("\\\\")
		case '\b':
			buf.WriteString("\\b")
		case '\f':
			buf.WriteString("\\f")
		case '\n':
			buf.WriteString("\\n")
		case '\r':
			buf.WriteString("\\r")
		case '\t':
			buf.WriteString("\\t")
		default:
			if r < 0x20 || r == 0x7F || (r >= 0x80 && r <= 0x9F) || r == 0x2028 || r == 0x2029 {
				fmt.Fprintf(&buf, "\\u%04X", r)
			} else {
				buf.WriteRune(r)
			}
		}
	}
	buf.WriteByte('"')
	return buf.String()
}

func isURL(s string) bool {
	l := strings.ToLower(s)
	return strings.HasPrefix(l, "http://") || strings.HasPrefix(l, "https://")
}

func isTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

type statement struct {
	path  []interface{} // string for keys, int for indices
	value interface{}    // nil, bool, string, json.Number, map (for {}), slice (for [])
	isEmptyObj bool
	isEmptyArr bool
	// For gron generation, we need to know if value is object/array vs primitive
	// We'll store raw value and determine type
}

func main() {
	var ungronFlag, valuesFlag, colorizeFlag, monochromeFlag, streamFlag, insecureFlag, jsonFlag, noSortFlag, versionFlag bool
	var proxyFlag, noproxyFlag string

	flag.BoolVar(&ungronFlag, "u", false, "")
	flag.BoolVar(&ungronFlag, "ungron", false, "")
	flag.BoolVar(&valuesFlag, "v", false, "")
	flag.BoolVar(&valuesFlag, "values", false, "")
	flag.BoolVar(&colorizeFlag, "c", false, "")
	flag.BoolVar(&colorizeFlag, "colorize", false, "")
	flag.BoolVar(&monochromeFlag, "m", false, "")
	flag.BoolVar(&monochromeFlag, "monochrome", false, "")
	flag.BoolVar(&streamFlag, "s", false, "")
	flag.BoolVar(&streamFlag, "stream", false, "")
	flag.BoolVar(&insecureFlag, "k", false, "")
	flag.BoolVar(&insecureFlag, "insecure", false, "")
	flag.StringVar(&proxyFlag, "x", "", "")
	flag.StringVar(&proxyFlag, "proxy", "", "")
	flag.StringVar(&noproxyFlag, "noproxy", "", "")
	flag.BoolVar(&jsonFlag, "j", false, "")
	flag.BoolVar(&jsonFlag, "json", false, "")
	flag.BoolVar(&noSortFlag, "no-sort", false, "")
	flag.BoolVar(&versionFlag, "version", false, "")

	flag.Usage = func() {
		fmt.Fprint(os.Stderr, helpText)
	}
	flag.Parse()

	if versionFlag {
		fmt.Fprint(os.Stdout, "gron version dev\n")
		os.Exit(0)
	}

	// argv0 check: suffix "ungron"
	if strings.HasSuffix(os.Args[0], "ungron") {
		ungronFlag = true
	}

	// precedence: ungron > values
	// color determination
	useColor := false
	if colorizeFlag {
		useColor = true
	} else if monochromeFlag {
		useColor = false
	} else {
		if isTTY() {
			useColor = true
		} else {
			useColor = false
		}
	}

	args := flag.Args()
	var inputArg string
	hasArg := false
	if len(args) > 0 {
		inputArg = args[0]
		hasArg = true
	}

	// Handle values quirk: if values and hasArg (file/URL), try to open/fetch to check errors, but read stdin
	if valuesFlag && !ungronFlag {
		if hasArg && inputArg != "-" && !isURL(inputArg) {
			// file: try open
			f, err := os.Open(inputArg)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
			f.Close()
			// then read stdin (ignore file content)
			doValues(os.Stdin, useColor)
			return
		} else if hasArg && isURL(inputArg) {
			// fetch URL to check errors, discard, then read stdin
			_, err := fetchURL(inputArg, proxyFlag, noproxyFlag, insecureFlag)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(4)
			}
			doValues(os.Stdin, useColor)
			return
		} else {
			// no arg or "-" => stdin
			var r io.Reader
			if hasArg && inputArg == "-" {
				r = os.Stdin
			} else if !hasArg {
				r = os.Stdin
			} else {
				r = os.Stdin
			}
			doValues(r, useColor)
			return
		}
	}

	if ungronFlag {
		// ungron mode
		var data []byte
		var err error
		if !hasArg || (hasArg && inputArg == "-") {
			data, err = io.ReadAll(os.Stdin)
			if err != nil {
				fmt.Fprintln(os.Stderr, "failed to read input statements")
				os.Exit(2)
			}
		} else if isURL(inputArg) {
			data, err = fetchURL(inputArg, proxyFlag, noproxyFlag, insecureFlag)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(4)
			}
		} else {
			// file
			f, err := os.Open(inputArg)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
			data, err = io.ReadAll(f)
			f.Close()
			if err != nil {
				fmt.Fprintln(os.Stderr, "failed to read input statements")
				os.Exit(2)
			}
		}
		if jsonFlag {
			doUngronJSON(data, useColor)
		} else {
			doUngron(data, useColor)
		}
		return
	}

	// gron mode (including stream, json)
	if streamFlag {
		doGronStream(hasArg, inputArg, proxyFlag, noproxyFlag, insecureFlag, jsonFlag, noSortFlag, useColor)
		return
	}

	// non-stream gron
	var reader io.Reader
	var fileToClose *os.File
	var urlData []byte
	isURLInput := false
	if !hasArg || (hasArg && inputArg == "-") {
		reader = os.Stdin
	} else if isURL(inputArg) {
		var err error
		urlData, err = fetchURL(inputArg, proxyFlag, noproxyFlag, insecureFlag)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(4)
		}
		reader = bytes.NewReader(urlData)
		isURLInput = true
		_ = isURLInput
	} else {
		f, err := os.Open(inputArg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fileToClose = f
		reader = f
	}
	if fileToClose != nil {
		defer fileToClose.Close()
	}
	dec := json.NewDecoder(reader)
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
		os.Exit(3)
	}
	// generate statements
	stmts := generateStatements(v, !noSortFlag)
	if jsonFlag {
		outputJSONStream(stmts, useColor)
	} else {
		outputGron(stmts, useColor)
	}
}

func fetchURL(urlStr, proxyStr, noproxyStr string, insecure bool) ([]byte, error) {
	transport := &http.Transport{
		Proxy: nil,
	}
	if proxyStr != "" {
		proxyURL, err := url.Parse(proxyStr)
		if err == nil {
			// check: if proxyURL.Host == "" and proxyStr != ""? For "invalidproxy", Host=="", but original still tries proxy (dial :0)
			// For "" (empty), no proxy (but we already check proxyStr != "")
			// For "127.0.0.1:1" which fails Parse, err != nil => no proxy (direct)
			// So if err==nil, use proxy even if Host==""
			// Need noproxy handling: exact match on req host?
			noproxyList := []string{}
			if noproxyStr != "" {
				parts := strings.Split(noproxyStr, ",")
				for _, p := range parts {
					noproxyList = append(noproxyList, p)
				}
			}
			transport.Proxy = func(req *http.Request) (*url.URL, error) {
				// check noproxy exact match on req.URL.Host?
				h := req.URL.Host
				for _, np := range noproxyList {
					if h == np {
						return nil, nil
					}
				}
				return proxyURL, nil
			}
		} else {
			// parse error => no proxy (direct)
			transport.Proxy = nil
		}
	} else {
		transport.Proxy = nil
	}
	if insecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	client := &http.Client{Transport: transport}
	resp, err := client.Get(urlStr)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	return data, nil
}

func generateStatements(v interface{}, doSort bool) []statement {
	var stmts []statement
	// root
	stmts = append(stmts, statement{path: []interface{}{}, value: v})
	// traverse
	var traverse func(path []interface{}, val interface{})
	traverse = func(path []interface{}, val interface{}) {
		switch vv := val.(type) {
		case map[string]interface{}:
			var keys []string
			for k := range vv {
				keys = append(keys, k)
			}
			if doSort {
				// partition bare vs quoted
				var bare, quoted []string
				for _, k := range keys {
					if isBare(k) {
						bare = append(bare, k)
					} else {
						quoted = append(quoted, k)
					}
				}
				sort.Strings(bare)
				sort.Strings(quoted)
				keys = append(bare, quoted...)
			} else {
				// random order: use as is from map iteration? But we already collected via range which is random.
				// However we collected once, so order is already random. Don't sort.
				// But need to ensure random? Go map iteration is random, so keys order is random. Good.
			}
			for _, k := range keys {
				childVal := vv[k]
				childPath := append(append([]interface{}{}, path...), k)
				stmts = append(stmts, statement{path: childPath, value: childVal})
				traverse(childPath, childVal)
			}
		case []interface{}:
			for i, childVal := range vv {
				childPath := append(append([]interface{}{}, path...), i)
				stmts = append(stmts, statement{path: childPath, value: childVal})
				traverse(childPath, childVal)
			}
		default:
			// primitive, no children
		}
	}
	traverse([]interface{}{}, v)
	// For --no-sort, the order of stmts beyond per-level? Our traverse already depth-first with random per-level.
	// For sorted, traverse depth-first with sorted per-level gives globally sorted? Good.
	// But need to ensure root first, then depth-first. That's what we do.
	return stmts
}

func formatPath(path []interface{}) string {
	var buf bytes.Buffer
	buf.WriteString("json")
	for _, p := range path {
		switch vv := p.(type) {
		case string:
			if isBare(vv) {
				buf.WriteString(".")
				buf.WriteString(vv)
			} else {
				buf.WriteString("[")
				buf.WriteString(encodeGronString(vv))
				buf.WriteString("]")
			}
		case int:
			fmt.Fprintf(&buf, "[%d]", vv)
		}
	}
	return buf.String()
}

func formatValue(v interface{}) string {
	switch vv := v.(type) {
	case nil:
		return "null"
	case bool:
		if vv {
			return "true"
		}
		return "false"
	case string:
		return encodeGronString(vv)
	case json.Number:
		return string(vv)
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	default:
		// Should not happen: numbers decoded as json.Number, but what about float64? With UseNumber, all numbers are json.Number.
		// But just in case:
		return fmt.Sprintf("%v", vv)
	}
}

func outputGron(stmts []statement, useColor bool) {
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, s := range stmts {
		pathStr := formatPath(s.path)
		valStr := formatValue(s.value)
		if !useColor {
			fmt.Fprintf(w, "%s = %s;\n", pathStr, valStr)
		} else {
			// colorize path and value
			coloredPath := colorizePath(s.path)
			coloredVal := colorizeValue(s.value, valStr)
			fmt.Fprintf(w, "%s = %s;\n", coloredPath, coloredVal)
		}
	}
}

func colorizePath(path []interface{}) string {
	var buf bytes.Buffer
	// json in blue bold
	buf.WriteString("\x1b[34;1mjson\x1b[0;22m")
	for _, p := range path {
		switch vv := p.(type) {
		case string:
			if isBare(vv) {
				buf.WriteString(".")
				buf.WriteString("\x1b[34;1m" + vv + "\x1b[0;22m")
			} else {
				buf.WriteString("\x1b[35m[\x1b[0m")
				buf.WriteString("\x1b[33m" + encodeGronString(vv) + "\x1b[0m")
				buf.WriteString("\x1b[35m]\x1b[0m")
			}
		case int:
			buf.WriteString("\x1b[35m[\x1b[0m")
			buf.WriteString(fmt.Sprintf("\x1b[31m%d\x1b[0m", vv))
			buf.WriteString("\x1b[35m]\x1b[0m")
		}
	}
	return buf.String()
}

func colorizeValue(v interface{}, valStr string) string {
	switch vv := v.(type) {
	case nil:
		return "\x1b[36mnull\x1b[0m"
	case bool:
		if vv {
			return "\x1b[36mtrue\x1b[0m"
		}
		return "\x1b[36mfalse\x1b[0m"
	case string:
		return "\x1b[33m" + valStr + "\x1b[0m"
	case json.Number:
		return "\x1b[31m" + valStr + "\x1b[0m"
	case map[string]interface{}:
		return "\x1b[35m{}\x1b[0m"
	case []interface{}:
		return "\x1b[35m[]\x1b[0m"
	default:
		_ = vv
		return valStr
	}
}

func outputJSONStream(stmts []statement, useColor bool) {
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, s := range stmts {
		// path encoding: JSON array of strings/ints
		// value encoding: JSON value with gron string encoding, numbers raw
		pathPart := encodeJSONPath(s.path)
		valPart := encodeJSONValue(s.value)
		if !useColor {
			fmt.Fprintf(w, "[%s,%s]\n", pathPart, valPart)
		} else {
			// colorize: outer brackets magenta, inner path brackets magenta, strings yellow, numbers red, etc.
			// Format: \x1b[35m[\x1b[0m + pathColored + , + valColored + \x1b[35m]\x1b[0m
			// pathColored: \x1b[35m[\x1b[0m + elements (comma plain) + \x1b[35m]\x1b[0m
			// elements: strings yellow, numbers red
			coloredPathInner := colorizeJSONPath(s.path)
			coloredVal := colorizeJSONValue(s.value, valPart)
			// outer: [ pathInner , val ]
			// pathInner already includes its own brackets? Let's construct:
			// Full: magenta[ + magenta[ + ... + magenta] + , + val + magenta]
			// Our coloredPathInner should be like magenta[ + ... + magenta]
			fmt.Fprintf(w, "\x1b[35m[\x1b[0m%s,%s\x1b[35m]\x1b[0m\n", coloredPathInner, coloredVal)
		}
	}
}

func encodeJSONPath(path []interface{}) string {
	if len(path) == 0 {
		return "[]"
	}
	var buf bytes.Buffer
	buf.WriteString("[")
	for i, p := range path {
		if i > 0 {
			buf.WriteString(",")
		}
		switch vv := p.(type) {
		case string:
			buf.WriteString(encodeGronString(vv))
		case int:
			fmt.Fprintf(&buf, "%d", vv)
		}
	}
	buf.WriteString("]")
	return buf.String()
}

func encodeJSONValue(v interface{}) string {
	switch vv := v.(type) {
	case nil:
		return "null"
	case bool:
		if vv {
			return "true"
		}
		return "false"
	case string:
		return encodeGronString(vv)
	case json.Number:
		return string(vv)
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	default:
		return fmt.Sprintf("%v", vv)
	}
}

func colorizeJSONPath(path []interface{}) string {
	var buf bytes.Buffer
	buf.WriteString("\x1b[35m[\x1b[0m")
	for i, p := range path {
		if i > 0 {
			buf.WriteString(",")
		}
		switch vv := p.(type) {
		case string:
			buf.WriteString("\x1b[33m" + encodeGronString(vv) + "\x1b[0m")
		case int:
			buf.WriteString(fmt.Sprintf("\x1b[31m%d\x1b[0m", vv))
		}
	}
	buf.WriteString("\x1b[35m]\x1b[0m")
	return buf.String()
}

func colorizeJSONValue(v interface{}, valPart string) string {
	switch vv := v.(type) {
	case nil:
		return "\x1b[36mnull\x1b[0m"
	case bool:
		if vv {
			return "\x1b[36mtrue\x1b[0m"
		}
		return "\x1b[36mfalse\x1b[0m"
	case string:
		return "\x1b[33m" + valPart + "\x1b[0m"
	case json.Number:
		return "\x1b[31m" + valPart + "\x1b[0m"
	case map[string]interface{}:
		return "\x1b[35m{}\x1b[0m"
	case []interface{}:
		return "\x1b[35m[]\x1b[0m"
	default:
		_ = vv
		return valPart
	}
}

func doGronStream(hasArg bool, inputArg, proxyStr, noproxyStr string, insecure, jsonFlag, noSortFlag, useColor bool) {
	var reader io.Reader
	var fileToClose *os.File
	if !hasArg || (hasArg && inputArg == "-") {
		reader = os.Stdin
	} else if isURL(inputArg) {
		data, err := fetchURL(inputArg, proxyStr, noproxyStr, insecure)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(4)
		}
		reader = bytes.NewReader(data)
	} else {
		f, err := os.Open(inputArg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fileToClose = f
		reader = f
	}
	if fileToClose != nil {
		defer fileToClose.Close()
	}
	// read lines using bufio.Reader to avoid 64k limit, mimic Scanner behavior
	br := bufio.NewReader(reader)
	var lines []string
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				// if line != "" (without newline at EOF), treat as line? For '' (empty), line=="" and EOF => 0 lines.
				// For '{"a":1}' (no newline), line='{"a":1}' and EOF => 1 line.
				// For '{"a":1}\n' (with newline), previous iteration already consumed line with newline, now EOF with line=="" => no extra line.
				if line != "" {
					// remove trailing \n? line doesn't have \n here (since EOF without newline), but may have \r?
					// Actually ReadString returns data up to EOF without delimiter.
					lines = append(lines, line)
				}
				break
			} else {
				// read error (e.g., directory)
				// output header + already parsed? For directory, no lines parsed yet, output header?
				// Original: output 'json = [];\n' + error "error reading multiline input: read /tmp: is a directory: %!s(MISSING)"
				// Need to generate partial statements for already parsed lines? For directory, 0 lines parsed, so just header.
				// For other cases where some lines parsed then read error? Hard to trigger (only directory at start).
				// We'll output partial and error.
				// Build array from lines parsed so far (lines slice before error)
				arr := make([]interface{}, len(linesParsed))
				// ... need to handle linesParsed vs lines?
				// Simpler: print header and parsed, then error
				// Use linesParsed global? We'll need to restructure.
				// For now, handle directory case: output header
				// The error message format: "error reading multiline input: %s: %s" with missing arg => need to replicate exactly
				// Original: fmt.Sprintf("error reading multiline input: %s: %s", err) with one arg? That gives "%!s(MISSING)"
				// We'll do: fmt.Fprintf(os.Stderr, "error reading multiline input: %s: %s\n", err)
				// In Go, missing arg gives "%!s(MISSING)" automatically. Good.
				// But need to output partial statements first to stdout.
				// For directory, partial is empty array.
				// Let's output.
				// We need linesParsed values; for now assume 0.
				// This branch is for read error before any lines? Actually for directory, first ReadString fails immediately.
				// So lines is empty.
				// Output empty array statements.
				emptyStmts := generateStatements([]interface{}{}, !noSortFlag)
				// But for stream with error, should we output parsed lines? For directory, 0 lines => empty array.
				// For other read errors mid-stream? Unlikely.
				// We'll output based on lines parsed so far (need to track parsed values, not just lines).
				// To simplify, we'll handle read errors in loop below with parsed values.
				fmt.Fprintf(os.Stderr, "error reading multiline input: %s: %s\n", err)
				// output header? Need to decide order: stdout first, then stderr? Original outputs stdout (header) + stderr (error). Order doesn't matter for test (separate streams).
				// We'll output header now.
				if jsonFlag {
					outputJSONStream(emptyStmts, useColor)
				} else {
					outputGron(emptyStmts, useColor)
				}
				os.Exit(3)
			}
		} else {
			// line ends with \n, strip trailing \n and \r? Scanner strips \r\n? bufio.Scanner strips \r? ReadString keeps \r\n.
			// Need to mimic Scanner: it strips trailing \r? For lines with \r\n, Scanner returns without \r.
			// We'll strip single trailing \n, then single trailing \r if present.
			if strings.HasSuffix(line, "\n") {
				line = line[:len(line)-1]
				if strings.HasSuffix(line, "\r") {
					line = line[:len(line)-1]
				}
			}
			lines = append(lines, line)
		}
	}
	// Now parse each line as JSON
	var values []interface{}
	for idx, line := range lines {
		dec := json.NewDecoder(strings.NewReader(line))
		dec.UseNumber()
		var v interface{}
		if err := dec.Decode(&v); err != nil {
			// error: output partial (values so far as array) + error
			arr := make([]interface{}, len(values))
			copy(arr, values)
			stmts := generateStatements(arr, !noSortFlag)
			if jsonFlag {
				outputJSONStream(stmts, useColor)
			} else {
				outputGron(stmts, useColor)
			}
			fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
			os.Exit(3)
			_ = idx
			return
		}
		values = append(values, v)
	}
	// success: output array
	arr := make([]interface{}, len(values))
	copy(arr, values)
	stmts := generateStatements(arr, !noSortFlag)
	if jsonFlag {
		outputJSONStream(stmts, useColor)
	} else {
		outputGron(stmts, useColor)
	}
}

